from html import escape as e
from pathlib import Path

ROOT = Path(__file__).parent
S = {
'rate': ('SF Rent Board · current rates', 'https://www.sf.gov/reports--current-rates-including-rent-increase-relocation-sec-deposit'),
'overview': ('SF Rent Board · rent increases', 'https://www.sf.gov/learn-about-rent-increases-san-francisco'),
'bank': ('SF Rent Board · banking', 'https://www.sf.gov/information--banked-rent-increases'),
'inventory': ('SF Rent Board · housing inventory', 'https://www.sf.gov/rent-board-housing-inventory'),
'coverage': ('SF Rent Board · rental laws', 'https://www.sf.gov/learn-about-san-francisco-rental-laws'),
'roommates': ('SF Rent Board · roommates', 'https://www.sf.gov/information--rent-increases-under-section-614-and-costa-hawkins'),
'ordinance': ('SF Rent Board · rent limitations', 'https://www.sf.gov/information--sec-373-rent-limitations'),
'state': ('SF Rent Board · AB 1482', 'https://www.sf.gov/reports--california-tenant-protection-act-2019-ab-1482'),
'rights': ('California Civil Rights Department · housing', 'https://calcivilrights.ca.gov/housing/'),
'federal': ('HUD · Fair Housing Act', 'https://www.hud.gov/news/hud-no-26-069'),
'fees': ('SF Rent Board · O&M petition', 'https://www.sf.gov/file/530-om-petition-fillable-324pdf'),
'capital': ('SF Rent Board · capital improvements', 'https://www.sf.gov/information--capital-improvement-petitions'),
'forms': ('SF Rent Board · forms', 'https://www.sf.gov/rent-board-forms-forms-center'),
'help': ('SF Rent Board · referrals', 'https://www.sf.gov/reports/november-2024/rent-board-referral-listing'),
'legal': ('SF · housing trust fund report', 'https://media.api.sf.gov/documents/120882_-_Housing_Trust_Fund_Five-Year_Report_-_2018-2023.pdf'),
'counsel': ('SF Rent Board · rental laws & counseling', 'https://www.sf.gov/learn-about-san-francisco-rental-laws'),
'notice': ('SF Rent Board · notice rules', 'https://www.sf.gov/reports--december-2022--rent-board-rules-and-regulations-part-iv-rent-increases-not-requiring'),
}
def links(*keys):
 return ' · '.join(f'<a href="{e(S[k][1], quote=True)}">{e(S[k][0])} ↗</a>' for k in keys)
def table(headers, rows):
 return '<div class="table-wrap"><table><thead><tr>' + ''.join('<th scope="col">'+e(x)+'</th>' for x in headers) + '<th scope="col">Official source</th></tr></thead><tbody>' + ''.join('<tr>'+''.join('<td>'+x+'</td>' for x in cells)+'<td class="source">'+links(*src)+'</td></tr>' for cells,src in rows)+'</tbody></table></div>'
PAGES = [ ('index.html','Overview'),('calculations.html','Unit scenarios'),('rules.html','Rules & fairness'),('notice.html','Notice & resources'),('review.html','Flagged for review') ]
def page(file, eyebrow, title, intro, content):
 nav = ''.join(f'<a href="{f}"'+(' aria-current="page"' if f == file else '')+'>'+n+'</a>' for f,n in PAGES)
 out=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="An anonymized, source-linked San Francisco rental increase research dashboard."><title>{e(title)} | Rental review</title><link rel="stylesheet" href="style.css"></head><body><a class="skip" href="#content">Skip to content</a><header><div class="top"><a class="brand" href="index.html"><span class="mark">R</span><span>RENTAL REVIEW<small>San Francisco · 94122</small></span></a><span class="snapshot">RESEARCH SNAPSHOT <b>06 NOV 2026</b></span></div><nav aria-label="Main navigation">{nav}</nav></header><main id="content"><div class="intro"><p class="eyebrow">{eyebrow}</p><h1>{e(title)}</h1><p class="lede">{intro}</p></div>{content}</main><footer><span>Prepared from public official sources · November 6, 2026</span><span>Research, not legal advice. No attorney review has occurred.</span></footer></body></html>'''
 (ROOT/file).write_text(out,encoding='utf-8')

cases = table(['Unit','Hypothetical annual increase','Hypothetical new base','Condition'],[
 (['Unit 1','$63.92 / month','$4,058.92 / month','1.6% × reported $3,995; no banked increases included.'],['rate','overview']),
 (['Unit 2','$50.40 / month','$3,200.40 / month','1.6% × reported $3,150; no banked increases included.'],['rate','overview'])])
page('index.html','EXECUTIVE SUMMARY','A measured approach to rent increases','A practical, tenant-conscious review of two reported rent-controlled tenancies in the Outer Sunset.',f'''
<div class="callout"><strong>Decision, not a legal clearance.</strong> Consider the same modest annual-only percentage for each unit, or less, after independently confirming eligibility, lawful base rents, lease terms, last increases, and current licenses. Neither this research nor equal percentages guarantee compliance or prevent a discrimination claim.</div>
<div class="stats"><article><span>CURRENT ANNUAL ALLOWANCE</span><strong>1.6%</strong><small>Mar 1, 2026 – Feb 28, 2027 · <a href="{S['rate'][1]}">Rent Board ↗</a></small></article><article><span>APPROACH</span><strong>Annual only</strong><small>No banked increases assumed</small></article><article><span>CASE STATUS</span><strong>Review first</strong><small>Private records not verified</small></article></div>
<section><div class="section-head"><div><p class="eyebrow">THE SHORT ANSWER</p><h2>A simple starting point</h2></div><a class="text-link" href="calculations.html">See calculation details →</a></div><p>The Rent Board’s current 1.6% annual allowance is a defensible benchmark, not a finding of a “normal” market increase or a requirement to raise rent. A smaller increase or no increase is also an option. These examples assume the reported rents are lawful base rents and every precondition is met.</p>{cases}<p class="footnote">Figures are arithmetic illustrations from unverified case inputs, not official rent determinations or ready-to-serve amounts.</p></section>
<div class="split"><section class="panel"><p class="eyebrow">BEFORE ANY NOTICE</p><h2>Confirm the basics</h2><ul><li>Coverage and exemptions for each unit.</li><li>Lease terms, base rent and full rent history.</li><li>12-month timing and current rent increase license.</li><li>Written notice, service and a neutral rationale.</li></ul><a class="text-link" href="notice.html">Review the checklist →</a></section><section class="panel dark"><p class="eyebrow">TENANT-FIRST CHECK</p><h2>Fairness needs evidence</h2><p>A change in roommates alone is not a reason to charge extra. One unit can be treated differently for a legitimate, documented reason, but raising both does not immunize a decision.</p><a href="rules.html">Explore the safeguards →</a></section></div>
<section class="review-banner"><div><p class="eyebrow">OPEN ITEMS</p><h2>Unverified does not mean resolved.</h2><p>Coverage, licenses, legal rent and actual notice dates cannot be established from public research alone.</p></div><a class="button" href="review.html">View flagged items <span>→</span></a></section>''')

page('calculations.html','01 / CASE ANALYSIS','Unit scenarios','Illustrative arithmetic, not a verified lawful rent or a notice to tenants.',f'''
<div class="callout"><strong>Evidence boundary.</strong> The dates, amounts, neighborhood, claimed 1940 construction and continuing tenancy below were supplied by the requester. No lease, official property record, payment ledger or license was provided or independently checked. They remain unverified; source links explain the governing method, not proof of these private facts.</div>
<section><h2>Reported case inputs</h2><p>Unit 1: last lease began February 1, 2025 at $3,995 per month; a continuing tenancy was reported on April 1, 2026 at $3,995 per month. One initial occupant is reported to remain. Unit 2: last lease began June 1, 2019 at $3,150 per month. The requester reports both units are rent-controlled and the building was built in 1940. No identifying names or initials are published.</p><p>The latest reported Unit 2 figure dates to 2019; it is not verified to be the current lawful base rent. Occupancy, tenancy continuity and last lawful increase are also unverified for both units.</p></section>
<section><h2>Annual-only illustration</h2><p>For an effective date between March 1, 2026 and February 28, 2027, apply 1.6% to the lawful base rent, excluding temporary passthroughs. Do not round up to the next dollar. The illustrated amounts assume no prior increase within 12 months and no contractual bar, among other conditions.</p>{cases}<p class="footnote">The percentage is official; amounts are calculated from user-reported, unverified inputs. Neither row establishes an effective date or an entitlement to increase.</p></section>
<section><h2>Timing and banked increases</h2>{table(['Question','Assessment'],[
(['Unit 1 · Feb 1, 2026','If the original February 1, 2025 tenancy continued and no increase occurred, the rate in effect on February 1, 2026 was 1.4%. That date is past; this is not a retroactive charge.'],['rate','overview']),
(['Unit 1 · 2026–27','If no earlier increase occurred and the tenancy continued, a later eligible effective date within the 1.6% period may use that rate. A skipped increase must mature before banking; if an increase takes effect before 24 full months pass, the skipped amount can be lost. Confirm the anniversary and lease terms.'],['bank','overview']),
(['Unit 2 · banked','The possible banked amount is <strong>unverified</strong>. A 2019 lease alone does not prove no increases occurred or that the current lawful base is $3,150. Do not calculate or impose a banked balance without the complete rent history.'],['bank']),
(['Effective dates','<span class="blank">—</span> <span class="tag">UNVERIFIED</span> No service date, last-increase dates, lease restrictions, or license status were supplied. A late increase establishes a new anniversary.'],['overview','inventory'])])}</section>''')

page('rules.html','02 / LEGAL FRAMEWORK','Rules & fairness','Compare the applicable protections before deciding whether, when, or how much to increase.',f'''
<section><h2>The legal framework</h2>{table(['Layer','What the source says'],[
(['Local · coverage','Many pre-June 14, 1979 units have rent control, but exceptions can apply, including certain single-family homes, condos and substantially rehabilitated units. The reported build year alone does not establish coverage.'],['coverage']),
(['Local · annual','1.6% applies to the annual allowable increase effective March 1, 2026 through February 28, 2027. This is citywide, not a ZIP-specific rate. Covered annual increases generally occur no more than once every 12 months.'],['rate','overview']),
(['Local · license','A current rent increase license must be on file before an annual or banked increase takes effect. Housing Inventory reporting is needed; status for these units is unknown.'],['inventory']),
(['State · AB 1482','The Rent Board reports 8.8% for covered AB 1482 units in San Francisco from August 1, 2026 through July 31, 2027. It does not replace or authorize bypassing stricter local rent control. Do not use 8.8% for the stated rent-controlled scenario.'],['state']),
(['Federal · fair housing','The Fair Housing Act prohibits discrimination in rental housing on specified protected grounds, including race, color, national origin, religion, sex, familial status and disability. Federal program rules may add conditions if applicable; no program status was supplied.'],['federal']),
(['California · fairness','California protects additional characteristics, including source of income, and prohibits retaliation for exercising fair housing rights. A matching increase cannot itself establish nondiscrimination.'],['rights'])])}</section>
<section><h2>One unit or both?</h2><p>There is no rule here requiring both units to receive an increase at the same time. A consistent annual-only percentage for eligible units is a cautious policy choice, not a safe harbor. Different timing, base rents, lease terms or a documented decision to defer can justify different outcomes, but must be assessed individually. Do not rely on protected characteristics, complaints or other retaliatory reasons; a neutral policy may still merit legal review for discriminatory effects.</p><p>Privately document the eligibility and objective basis for each decision. Do not publish tenant records. A local attorney should review the full facts before service. {links('rights','federal')}</p></section>
<section><h2>Owners and reasons</h2>{table(['Question','Finding'],[
(['Corporate vs. individual owners','No official, representative San Francisco dataset establishing typical increases by owner type was located. <strong>Typical percentages: <span class="blank">—</span> unverified.</strong> The Rent Board says many owners give annual and banked increases on the same date each year to avoid losing increases; it does not break this down by owner type. Both categories must comply with applicable law; do not treat corporate behavior as a legal benchmark.'],['overview','rights']),
(['Annual increase rationale','The ordinance permits a qualifying annual increase and the Rent Board says the maximum is optional. A transparent, neutral explanation such as an annual adjustment under the ordinance is more accurate than claiming unverified costs.'],['ordinance','bank']),
(['Operating costs','The annual allowance is intended to cover ordinary increases in operating and maintenance costs. Extraordinary O&M increases have a separate petition process; expenses alone do not authorize an extra charge.'],['fees']),
(['Capital improvements','Qualifying capital improvement costs have a separate petition, documentation and approval process. They are not simply folded into the annual base rent.'],['capital']),
(['Roommate change','The city says extra rent cannot be charged solely because an additional roommate moves in. The last-original-occupant rules are fact-specific; the reported remaining original occupant makes a vacancy reset inappropriate to assume.'],['overview','roommates'])])}</section>''')

page('notice.html','03 / IMPLEMENTATION','Notice & resources','A checklist and sample language for review—not a completed or legally sufficient notice.',f'''
<section><h2>Pre-notice checklist</h2>{table(['Step','What to confirm'],[
(['1 · Verify eligibility','Privately check coverage and exemptions, complete lease and amendments, current lawful base rent, prior notices and dates, and whether a fixed-term agreement permits the change.'],['coverage','overview']),
(['2 · License','Complete Housing Inventory reporting and confirm a current rent increase license is on file before the proposed annual or banked increase takes effect.'],['inventory']),
(['3 · Select a date','At least 12 months since the last annual increase or tenancy start as applicable; use the rate in effect on the actual effective date. No retroactive increase is proposed.'],['overview']),
(['4 · Written notice','The city describes 30 days for a cumulative increase of 10% or less in the preceding year, 90 days for more than 10%, plus 5 days if mailed. Verify service and exact timing with counsel.'],['overview','bank']),
(['5 · Content','State the dollar and percentage increase and effective date. Identify the annual and any banked portions; do not add banked amounts without substantiation. Confirm any other statutory, lease, subsidy or service requirements with counsel.'],['notice','bank']),
(['6 · Keep records','Retain the calculation, applicable rate, license, service evidence and neutral decision basis privately. Make no claim that legal counsel or tenants have approved the increase.'],['inventory','rights'])])}</section>
<section class="panel"><p class="eyebrow">DRAFT FOR COUNSEL ONLY</p><h2>Plain-language notice outline</h2><p>Dear [tenant placeholder],</p><p>Subject to a valid written notice and applicable law, the proposed annual rent adjustment is [percentage], or [monthly dollar amount], changing the monthly base rent from [current lawful base rent] to [new lawful base rent], effective [verified date]. The annual portion is [annual amount]; the banked portion, if any, is [verified amount or none].</p><p>This adjustment is proposed under the San Francisco Rent Ordinance. Please contact [property manager placeholder] with questions. You may contact the San Francisco Rent Board or seek independent tenant advice.</p><p class="footnote">Not for service as written. Names, addresses, delivery method, effective date, legal notices, and eligibility must be checked privately by counsel.</p></section>
<section><h2>Independent review and help</h2>{table(['Resource','Scope'],[
(['Rent Board','Counseling line: 415-252-4600. The Board provides information, not a personal lawyer or a guarantee of lawfulness.'],['counsel','state']),
(['Tenant support','The Rent Board referral list includes tenant counseling and legal-service organizations, including the Housing Rights Committee (free counseling, 415-703-8644). Availability and eligibility vary.'],['help']),
(['Eviction-related counsel','San Francisco’s Tenant Right to Counsel program provides free legal assistance for residents facing eviction; full-scope assistance is for eligible cases. Do not assume all rent-increase questions automatically qualify for free representation.'],['legal']),
(['Tenant petitions','The Rent Board lists Form 516C for unlawful rent increases and Form 518 for a pending unlawful increase. A tenant may seek independent review.'],['forms'])])}</section>''')

